import path from 'node:path';
import detectPort from 'detect-port';
import { DevModeInterfaceNonSingleton } from '../DevModeInterface.js';
import { DevModeUnifiedInterfaceNonSingleton } from '../DevModeUnifiedInterface.js';
import { buildLegacyComponents, buildUnifiedComponents, findProjectRoot, isLegacyPlatformVersion, loadProjectConfig, } from './configDiscovery.js';
import { createDevSessionManager } from './sessionManager.js';
export async function runDevCommand({ projectPath, port = '5173', accountId: accountIdStr, sdkVersionOverride, }) {
    const startPath = projectPath
        ? path.isAbsolute(projectPath)
            ? projectPath
            : path.resolve(process.cwd(), projectPath)
        : process.cwd();
    const requestedPort = parseInt(port, 10);
    const accountId = parseInt(accountIdStr ?? '', 10);
    const logger = {
        info: (...args) => console.log(...args),
        debug: (...args) => console.log(...args),
        warn: (...args) => console.error(...args),
        error: (...args) => console.error(...args),
    };
    const urls = {
        api: 'https://api.hubapi.com',
        web: 'https://app.hubspot.com',
    };
    const capturedPorts = {};
    const requestPorts = async (requests) => {
        const result = {};
        let nextPort = requestedPort;
        for (const { instanceId } of requests) {
            let portToUse = nextPort;
            try {
                const available = await detectPort(nextPort);
                if (available !== nextPort) {
                    logger.info(`Port ${nextPort} is in use, using ${available} instead`);
                }
                portToUse = available;
                nextPort = available + 1;
            }
            catch {
                nextPort += 1;
            }
            result[instanceId] = portToUse;
        }
        Object.assign(capturedPorts, result);
        return result;
    };
    const onUploadRequired = () => {
        logger.info('App config changed — restart uie dev to pick up the changes.');
    };
    try {
        if (isNaN(accountId)) {
            throw new Error('--account-id is required and must be a valid number');
        }
        const sessionManager = await createDevSessionManager(accountId, logger);
        let devMode;
        const shutdown = async () => {
            process.off('SIGINT', shutdown);
            process.off('SIGTERM', shutdown);
            await sessionManager?.cleanup();
            await devMode?.cleanup();
            process.exit(0);
        };
        process.on('SIGINT', shutdown);
        process.on('SIGTERM', shutdown);
        const projectDir = findProjectRoot(startPath);
        logger.info(`Starting dev server for project at ${projectDir}`);
        const projectConfig = loadProjectConfig(projectDir);
        if (isLegacyPlatformVersion(projectConfig.platformVersion)) {
            const components = buildLegacyComponents(projectDir, projectConfig);
            const legacyDevMode = new DevModeInterfaceNonSingleton();
            await legacyDevMode.setup({
                components,
                logger,
                urls,
                setActiveApp: async () => { },
                onUploadRequired,
                sdkVersionOverride,
            });
            await legacyDevMode.start({ accountId, requestPorts, projectConfig });
            devMode = legacyDevMode;
        }
        else {
            const { components, profileData } = await buildUnifiedComponents(projectDir, projectConfig, accountId);
            const unifiedDevMode = new DevModeUnifiedInterfaceNonSingleton();
            await unifiedDevMode.setup({
                components,
                profileData,
                platformVersion: projectConfig.platformVersion,
                logger,
                urls,
                setActiveApp: async () => { },
                onUploadRequired,
                sdkVersionOverride,
            });
            await unifiedDevMode.start({
                accountId,
                requestPorts,
                projectConfig,
            });
            devMode = unifiedDevMode;
        }
        if (sessionManager && Object.keys(capturedPorts).length > 0) {
            const ports = Object.entries(capturedPorts).map(([serverId, capturedPort]) => ({ serverId, port: capturedPort }));
            await sessionManager.register(ports).catch((err) => {
                logger.warn(`Failed to register local dev session: ${err instanceof Error ? err.message : String(err)}`);
            });
        }
    }
    catch (err) {
        logger.error('Error starting dev server:', err instanceof Error ? err.message : String(err));
        process.exit(1);
    }
}
